"code": "class Solution:\n    def canCompleteCircuit(self, gas: List[int], cost: List[int]) -> int:\n        if sum(gas) < sum(cost):\n            return -1\n        start, tank = 0, 0\n        for i in range(len(gas)):\n            tank += gas[i] - cost[i]\n            if tank < 0:          # can't reach i + 1 from start: try i + 1 next\n                start = i + 1\n                tank = 0\n        return start",
