"code": "class Solution:\n    def convert(self, s: str, numRows: int) -> str:\n        if numRows == 1 or numRows >= len(s):\n            return s\n        rows = [[] for _ in range(numRows)]\n        row, step = 0, 1\n        for ch in s:\n            rows[row].append(ch)\n            if row == 0:\n                step = 1              # bounce off the top\n            elif row == numRows - 1:\n                step = -1             # bounce off the bottom\n            row += step\n        return \"\".join(\"\".join(r) for r in rows)",
