"57": {
"id": 57,
"slug": "insert-interval",
"title": "Insert Interval",
"diff": "Medium",
"topic": "intervals",
"pattern": "Sweep",
"hook": "The intervals are sorted and don't overlap. Insert a new interval and merge where needed.",
"brute": "Append it and run Merge Intervals: O(n log n). The input is already sorted, so we can do O(n).",
"insight": "Three phases in one sweep: intervals that end before the new one starts are kept; intervals that overlap it are absorbed (widening it); intervals after it are kept.",
"steps": [
"Copy intervals with <code>end &lt; new.start</code>.",
"While <code>interval.start ≤ new.end</code>: widen the new interval to cover it.",
"Append the (widened) new interval, then copy the rest."
],
"code": "class Solution:\n    def insert(self, intervals: List[List[int]], newInterval: List[int]) -> List[List[int]]:\n        res = []\n        i, n = 0, len(intervals)\n        start, end = newInterval\n        while i < n and intervals[i][1] < start:      # completely before\n            res.append(intervals[i])\n            i += 1\n        while i < n and intervals[i][0] <= end:       # overlapping: absorb\n            start = min(start, intervals[i][0])\n            end = max(end, intervals[i][1])\n            i += 1\n        res.append([start, end])\n        while i < n:                                  # completely after\n            res.append(intervals[i])\n            i += 1\n        return res",
"time": "O(n)",
"space": "O(n)",
"run": "Solution().insert([[1, 2], [3, 5], [6, 7], [8, 10], [12, 16]], [4, 8])",
"expect": "[[1, 2], [3, 10], [12, 16]]",
"plans": [
"top150"
],
"traceSteps": 28
},
