"code": "class Solution:\n    def getMinimumDifference(self, root: Optional[TreeNode]) -> int:\n        best = float(\"inf\")\n        prev = None\n        def inorder(node):\n            nonlocal best, prev\n            if node is None:\n                return\n            inorder(node.left)\n            if prev is not None:\n                best = min(best, node.val - prev)   # sorted neighbours\n            prev = node.val\n            inorder(node.right)\n        inorder(root)\n        return best",
